import path from"path";import fastifyStatic from"@fastify/static";import fs from"node:fs";import{pipeline}from"node:stream/promises";import{getGlobalVariables}from"../action/setup-global-variables.js";import{PublicReturn}from"../common/public-return.js";import{createRouter as createPublicRouter}from"./public/index.js";import{createRouter as createSystemRouter}from"./system/index.js";import{createRouter as createFriendlyLinkRouter}from"./friendly-link.js";import{createRouter as createUserRouter}from"./user/index.js";import{createRouter as createNoteRouter}from"./note.js";import{createRouter as createWebRssRouter}from"./web/rss.js";import{createRouter as createWebSitemapRouter}from"./web/sitemap.js";import{createRouter as createWebRobotsRouter}from"./web/robots.js";export async function createRouter(e){const t=getGlobalVariables("webAdminDistDirPath");await e.register(async e=>{e.setNotFoundHandler(async(e,t)=>t.code(404).send(new PublicReturn(404,"接口 404 未注册",""))),await createPublicRouter(e),await createUserRouter(e),await createSystemRouter(e),await createFriendlyLinkRouter(e),await createNoteRouter(e)},{prefix:"/api"}),await e.register(async e=>{e.setNotFoundHandler(async(e,r)=>{try{const e=path.join(t,"index.html"),a=fs.createReadStream(e);a.on("error",e=>{r.code(404).type("text/html").send(getGlobalVariables("html404Str"))}),r.type("text/html"),await pipeline(a,r.raw)}catch(e){r.code(404).type("text/html").send(getGlobalVariables("html404Str"))}}),await e.register(fastifyStatic,{root:t,index:!1,list:!1,cacheControl:!0,maxAge:31536e3,setHeaders:(e,t)=>{"index.html"===path.basename(t)&&e.setHeader("Cache-Control","no-cache, no-store, must-revalidate")}})},{prefix:"/web-admin"}),await e.register(async e=>{await createWebRssRouter(e),await createWebSitemapRouter(e),await createWebRobotsRouter(e)},{prefix:"/"})}